// Title: How to remove redundant spaces from HTML generated by Aspose.Cells when saving a workbook in C#
// AI Prompts: Write C# code that saves an Aspose.Cells workbook as HTML and then uses a regular expression to collapse consecutive spaces into a single space. | Create a C# routine that trims trailing whitespace on each line of an HTML file produced by Aspose.Cells. | Implement a C# script that reads the HTML output from Aspose.Cells, removes extra spaces and empty lines, and overwrites the original file.
// Common Searches: aspocells c# save workbook as html remove extra whitespace | c# regex to clean up spaces in html file generated by Aspose.Cells | post processing html output from Aspose.Cells workbook.Save | how to trim trailing spaces in html saved by Aspose.Cells using C# | reduce multiple spaces in aspocells html export c#
// Tags: aspocells html whitespace cleanup c# | c# regex collapse multiple spaces | post‑processing aspocells html export | remove line‑end spaces in html file c# | collapse extra spaces in generated html

// Load an existing workbook (using the provided load rule)
Aspose.Cells.Workbook workbook = new Aspose.Cells.Workbook("input.xlsx");

// Save the workbook as HTML (using the provided save rule)
workbook.Save("output.html", Aspose.Cells.SaveFormat.Html);

// Post‑processing: remove redundant spaces from the generated HTML
string htmlContent = System.IO.File.ReadAllText("output.html");

// Replace sequences of two or more spaces with a single space
string cleanedHtml = System.Text.RegularExpressions.Regex.Replace(htmlContent, @" {2,}", " ");

// Optionally, also trim spaces at line ends
cleanedHtml = System.Text.RegularExpressions.Regex.Replace(cleanedHtml, @"[ \t]+(\r?\n)", "$1");

// Write the cleaned HTML back to the file
System.IO.File.WriteAllText("output.html", cleanedHtml);
